#if os(macOS)
import Foundation
import SwiftUI
import Testing
import ViewInspector
@testable import Loopflow
@testable import LoopflowMac

@Suite("Shared Task concepts")
@MainActor
struct TaskConceptTests {
    private struct Phase: Decodable {
        let name: String
        let tasks: [RoadmapTask]
        let sessions: [SessionRecord]
    }

    private var fixtures: URL {
        URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent().appendingPathComponent("tests/fixtures/dto")
    }

    /// Generated by the Rust roadmap projection, including its Session memberships.
    private func phases() throws -> [Phase] {
        try JSONDecoder().decode([Phase].self, from: Data(contentsOf: fixtures.appendingPathComponent("task_concepts.json")))
    }

    private func roadmap(_ phase: Phase) throws -> RoadmapSnapshot {
        var wire = try #require(JSONSerialization.jsonObject(
            with: Data(contentsOf: fixtures.appendingPathComponent("roadmap_snapshot.json"))) as? [String: Any])
        let source = try #require(JSONSerialization.jsonObject(
            with: Data(contentsOf: fixtures.appendingPathComponent("task_concepts.json"))) as? [[String: Any]])
        wire["tasks"] = ["state": "ok", "truncated": false,
                         "items": try #require(source.first { $0["name"] as? String == phase.name }?["tasks"])]
        var waves = try #require(wire["waves"] as? [[String: Any]])
        var wave = try #require(waves[0]["wave"] as? [String: Any])
        wave["id"] = try #require(phase.tasks.first?.task.waveId)
        wave["repo"] = "/repo"
        waves[0]["wave"] = wave
        wire["waves"] = [waves[0]]
        return try JSONDecoder().decode(RoadmapSnapshot.self, from: JSONSerialization.data(withJSONObject: wire))
    }

    private func activeTaskWire() throws -> [String: Any] {
        let phases = try #require(JSONSerialization.jsonObject(
            with: Data(contentsOf: fixtures.appendingPathComponent("task_concepts.json"))) as? [[String: Any]])
        return try #require((phases[0]["tasks"] as? [[String: Any]])?.first { $0["lifecycle"] as? String == "active" })
    }

    @Test func lifecycleAndActionsFollowTheSameRustReading() throws {
        for phase in try phases() {
            let model = WorkModel(query: RegistryQuery { _, _ in throw RegistryQueryError("Passive rendering") }, repoPath: "/repo")
            for task in phase.tasks {
                let header = TaskWorkflowHeader(model: model, task: task, work: .loading)
                let label = try header.inspect().find(viewWithAccessibilityIdentifier: "task-lifecycle-status").text().string()
                if task.task.identifier == "FIX-2" {
                    #expect(task.lifecycle == .active)
                    // Its worktree is missing, so the page says Blocked, as its row does.
                    #expect(label == "Blocked")
                    #expect(!task.awaitsStart)
                    #expect(!task.isCompleted)
                    #expect(TaskHistoryFilter().includes(task, now: .now))
                    #expect(task.opensConversationAutomatically)
                    #expect(task.isUnassigned == (phase.name == "unassigned_working"))
                    #expect(throws: (any Error).self) {
                        try TaskActionItems(model: model, task: task, wave: nil, work: nil).inspect().find(button: "Reopen Task")
                    }
                } else if task.isCompleted {
                    #expect(label == (task.lifecycle == .done ? "Done, date unavailable" : "Abandoned"))
                    _ = try TaskActionItems(model: model, task: task, wave: nil, work: nil).inspect().find(button: "Reopen Task")
                    #expect(!task.awaitsStart)
                    #expect(!task.opensConversationAutomatically)
                } else if task.lifecycle == .unstarted {
                    #expect(task.awaitsStart)
                }
            }
        }
    }

    private func applyTaskList(_ phase: Phase, to model: WorkModel) throws {
        let repository = try #require(phase.tasks.first?.task.repositoryId)
        let members = phase.tasks.map { task in
            WorkViewPlan.Content(
                work: .init(repository: repository, kind: .task, id: task.id), title: task.task.name,
                states: Array(task.selectionStates), identifier: task.task.identifier, primarySession: nil,
                location: nil, argv: nil, unavailable: [])
        }
        model.applyTaskList(fixtureViewPlan(owner: .init(repository: repository, kind: .repository, id: repository),
                                            members: members), wave: nil, reason: "")
    }

    @Test func selectedTaskKeepsItsSlotAcrossAConversationTurn() throws {
        let readings = try phases()
        let available = try #require(readings.first { $0.name == "owned_available" })
        let busy = try #require(readings.first { $0.name == "owned_working" })
        let first = try #require(available.tasks.first { $0.task.identifier == "FIX-1" }).id
        let second = try #require(available.tasks.first { $0.task.identifier == "FIX-2" }).id
        let model = WorkModel(query: RegistryQuery { _, _ in throw RegistryQueryError("Passive rendering") }, repoPath: "/repo")

        for (index, phase) in [available, busy, available].enumerated() {
            let roadmap = try roadmap(phase)
            model.applyFixture(roadmap: .available(roadmap), waves: .available([]), workActivity: .loading, repos: [])
            try applyTaskList(phase, to: model)
            if index == 0 {
                model.selectSidebarTask(slot: 1)
                model.navigation.selectedSessionId = "bound"
            }
            #expect(model.selection == .task(id: second))
            model.navigation.sidebarFilter = .working
            #expect(model.sidebarTaskIDs == [first, second])
            let wave = try #require(roadmap.waves.first)
            let picker = model.jumpRows(.wave(wave.wave.id), filter: "").map(\.id)
            #expect(picker.filter { $0 == .task(first) || $0 == .task(second) } == [.task(first), .task(second)])
            model.navigation.sidebarFilter = .busy
            #expect(model.sidebarTaskIDs == (phase.name == busy.name ? [second] : []))
            model.navigation.sidebarFilter = .available
            #expect(model.sidebarTaskIDs == (phase.name == busy.name ? [] : [second]))
            #expect(model.selection == .task(id: second))
            #expect(model.navigation.selectedSessionId == "bound")
        }
        model.navigation.sidebarFilter = .working
        model.cycleSidebarTask(1)
        #expect(model.selection == .task(id: first))
        model.selectSidebarTask(slot: 1)
        #expect(model.selection == .task(id: second))
    }

    @Test func boardPickerAndProjectionKeepServerOrderAndMembership() async throws {
        for phase in try phases() {
            let roadmap = try roadmap(phase)
            let entries = try JSONEncoder().encode(phase.sessions)
            let query = RegistryQuery { args, _ in
                if args.prefix(2) == ["session", "list"] {
                    return "{\"entries\":\(String(decoding: entries, as: UTF8.self)),\"next\":null}"
                }
                throw RegistryQueryError("Passive rendering")
            }
            let model = WorkModel(query: query, repoPath: "/repo")
            model.applyFixture(roadmap: .available(roadmap), waves: .available([]), workActivity: .loading, repos: [])
            await model.refreshSessions()
            try applyTaskList(phase, to: model)
            for filter in WorkNavigation.SidebarFilter.allCases {
                model.navigation.sidebarFilter = filter
                let expected = phase.tasks.filter { task in
                    task.selectionStates.contains(.working) && (filter == .working
                        || task.selectionStates.contains(filter == .available ? .available : .busy))
                }.map(\.id)
                #expect(model.sidebarTaskIDs == expected)
            }
            let wave = try #require(roadmap.waves.first)
            #expect(model.jumpRows(.wave(wave.wave.id), filter: "").map(\.id) == phase.tasks.map { .task($0.id) })
            let active = try #require(phase.tasks.first { $0.task.identifier == "FIX-2" })
            let picker = try #require(model.jumpRows(.wave(wave.wave.id), filter: "FIX-2").first)
            // The picker says the word the Task's row says.
            #expect(picker.detail == "FIX-2 · \(try #require(TaskRowStatus(task: active, status: model.programStatus(task: active.id)).word))")
            for task in phase.tasks where task.awaitsStart && task.need == nil {
                let row = model.jumpRows(.wave(wave.wave.id), filter: "").first { $0.id == .task(task.id) }
                #expect(row?.detail == "\(task.task.identifier) · Unstarted")
            }
            let projection = WorkProjection(roadmaps: roadmap.waves, inventory: phase.tasks, sessions: phase.sessions)
            let projected = try #require(projection.waves.first?.tasks)
            #expect(projected.map { $0.task.id } == phase.tasks.map(\.id))
            for task in projected {
                let expected = phase.sessions.filter { $0.taskIds.contains(task.task.id) }.map(\.id)
                #expect(task.sessions.map(\.id) == expected)
                #expect(model.taskSessions(task.task.id).map(\.id) == expected)
            }
            let siblings = try #require(projection.breadcrumb(selection: nil, sessionId: "checkout")?.siblings)
            #expect(Set(siblings.map(\.id)) == ["bound", "checkout", "unknown"])
        }
    }

    @Test func locationAndHistoricalAttributionDoNotInventMembership() throws {
        let phase = try #require(phases().first)
        let bound = try #require(phase.sessions.first { $0.id == "bound" })
        let task = try #require(bound.taskIds.first)
        var wire = try #require(JSONSerialization.jsonObject(with: JSONEncoder().encode(bound)) as? [String: Any])
        wire["task_ids"] = []
        let record = try JSONDecoder().decode(SessionRecord.self, from: JSONSerialization.data(withJSONObject: wire))
        #expect(!record.names(task: task))
        let roadmap = try roadmap(phase)
        let projection = WorkProjection(roadmaps: roadmap.waves, inventory: phase.tasks, sessions: [record])
        #expect(projection.waves.flatMap(\.tasks).allSatisfy { $0.sessions.isEmpty })
    }

    @Test func conversationReportsRemainSeparateFromTaskActivity() throws {
        let phase = try #require(phases().first { $0.name == "reclaimed_available_and_busy" })
        let task = try #require(phase.tasks.first { $0.task.identifier == "FIX-2" })
        let conversation = try #require(phase.sessions.first { $0.id == "bound" })
        #expect(task.selectionStates.contains(.busy))
        let status = SessionProgramStatus(sessions: [conversation], unavailable: nil)
        let row = TaskRow(id: task.id, presentation: .init(title: task.task.name, identifier: task.task.identifier, context: nil),
                          task: task, status: status)
        #expect(try row.inspect().find(text: "Blocked").string() == "Blocked")
        let programStatus = try #require(conversation.programStatus)
        let pane = try #require(StatusMark(status: programStatus))
        #expect(try pane.inspect().find(text: "Blocked").string() == "Blocked")
        #expect(task.lifecycle == .active)
    }

    @Test func membershipAndLifecycleSurviveAnAbsentRuntimePayload() throws {
        var row = try activeTaskWire()
        row["runtime"] = NSNull()
        var planning = try #require(row["task"] as? [String: Any])
        planning["wave_id"] = NSNull()
        row["task"] = planning
        let task = try JSONDecoder().decode(RoadmapTask.self, from: JSONSerialization.data(withJSONObject: row))
        let phase = try #require(self.phases().first)
        let projection = WorkProjection(roadmaps: [], inventory: [task], sessions: phase.sessions)
        #expect(Set(projection.standaloneTasks[0].sessions.map(\.id)) == ["bound", "checkout", "unknown"])
        #expect(task.lifecycle == .active)
        #expect(!task.awaitsStart)
        #expect(!task.isCompleted)
    }

    @Test func missingKeysFailAndSavedActivityCannotReturn() throws {
        var row = try activeTaskWire()
        for key in ["lifecycle", "selection_states"] {
            var missing = row
            missing.removeValue(forKey: key)
            #expect(throws: (any Error).self) {
                try JSONDecoder().decode(RoadmapTask.self, from: JSONSerialization.data(withJSONObject: missing))
            }
        }
        row["selection_states"] = ["active", "working", "available", "busy", "blocked"]
        let wire = String(decoding: try JSONSerialization.data(withJSONObject: row), as: UTF8.self)
        let quiet = try #require(WorkCache.quietRoadmap(wire))
        let restored = try JSONDecoder().decode(RoadmapTask.self, from: Data(quiet.utf8))
        #expect(restored.selectionStates == [.active, .working])
        #expect(restored.runControl.unavailable != nil)
    }
}
#endif
